<?php
declare(strict_types=1);
require_once __DIR__.'/config/communications_step21.php';
$error=null;$events=[];$outbox=[];$attempts=[];
try{$pdo=business_db();comm_step21_ensure($pdo);$ctx=comm_step21_context($pdo);$orgId=(int)$ctx['organization_id'];$s=$pdo->prepare("SELECT * FROM communication_events WHERE organization_id=? ORDER BY id DESC LIMIT 120");$s->execute([$orgId]);$events=$s->fetchAll();$s=$pdo->prepare("SELECT * FROM communication_outbox WHERE organization_id=? ORDER BY id DESC LIMIT 120");$s->execute([$orgId]);$outbox=$s->fetchAll();$s=$pdo->prepare("SELECT a.*,o.channel,o.recipient_name_snapshot FROM communication_attempts a JOIN communication_outbox o ON o.id=a.outbox_id WHERE a.organization_id=? ORDER BY a.id DESC LIMIT 120");$s->execute([$orgId]);$attempts=$s->fetchAll();}catch(Throwable $e){$error=$e->getMessage();}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Communication History - Healthcare Wellness Club</title><link rel="stylesheet" href="assets/dashboard.css"><link rel="stylesheet" href="assets/product_pro.css"></head><body><header class="os-topbar"><div class="os-topbar-inner"><a class="os-brand" href="communication_center.php"><img src="../img/logo.png"><span><strong>Healthcare Wellness Club</strong><small>Communication History</small></span></a><div class="os-top-actions"><a class="os-btn" href="communication_outbox.php">Outbox</a><a class="os-btn primary" href="communication_center.php">Communications</a></div></div></header><main class="os-main" style="max-width:1420px;margin:auto"><section class="os-hero pp-hero"><div class="os-kicker">STEP 21 • HISTORY</div><h1>Event, message and delivery-attempt evidence.</h1><p>Operational events are never confused with external delivery. Each layer has its own auditable history.</p></section><?php if($error):?><div class="pp-alert bad"><?=comm_step21_h($error)?></div><?php endif;?><section class="os-card" style="margin-top:14px"><h2>Operational Event History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Event</th><th>Entity</th><th>Severity</th><th>Status</th><th>Time</th></tr></thead><tbody><?php if(!$events):?><tr><td colspan="5">No events yet.</td></tr><?php endif;?><?php foreach($events as $r):?><tr><td><b><?=comm_step21_h($r['title'])?></b><br><small><?=comm_step21_h($r['event_type'])?></small></td><td><?=comm_step21_h(($r['entity_type']?:'—').($r['entity_id']?' #'.$r['entity_id']:''))?></td><td><?=comm_step21_h(strtoupper((string)$r['severity']))?></td><td><?=comm_step21_h(strtoupper((string)$r['event_status']))?></td><td><?=comm_step21_h($r['occurred_at'])?></td></tr><?php endforeach;?></tbody></table></div></section><section class="os-card" style="margin-top:14px"><h2>External Message History</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>ID</th><th>Channel</th><th>Recipient</th><th>Status</th><th>Attempts</th><th>Created / Sent</th></tr></thead><tbody><?php if(!$outbox):?><tr><td colspan="6">No external messages yet.</td></tr><?php endif;?><?php foreach($outbox as $r):?><tr><td>#<?=$r['id']?></td><td><?=comm_step21_h(strtoupper((string)$r['channel']))?></td><td><?=comm_step21_h($r['recipient_name_snapshot'])?><br><small><?=comm_step21_h($r['recipient_address_snapshot'])?></small></td><td><?=comm_step21_h(strtoupper(str_replace('_',' ',(string)$r['status'])))?></td><td><?=$r['attempts']?> / <?=$r['max_attempts']?></td><td><?=comm_step21_h($r['created_at'])?><?php if($r['sent_at']):?><br><small>Sent <?=comm_step21_h($r['sent_at'])?></small><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section><section class="os-card" style="margin-top:14px"><h2>Webhook Attempt Evidence</h2><div class="pp-table-wrap"><table class="pp-table"><thead><tr><th>Outbox</th><th>Channel</th><th>Recipient</th><th>Attempt</th><th>Outcome</th><th>Response</th><th>Time</th></tr></thead><tbody><?php if(!$attempts):?><tr><td colspan="7">No webhook delivery attempts yet.</td></tr><?php endif;?><?php foreach($attempts as $r):?><tr><td>#<?=$r['outbox_id']?></td><td><?=comm_step21_h(strtoupper((string)$r['channel']))?></td><td><?=comm_step21_h($r['recipient_name_snapshot'])?></td><td><?=$r['attempt_no']?></td><td><?=comm_step21_h(strtoupper((string)$r['outcome']))?></td><td><?=comm_step21_h(($r['response_code']?:'—').' '.($r['response_excerpt']?:''))?></td><td><?=comm_step21_h($r['attempted_at'])?></td></tr><?php endforeach;?></tbody></table></div></section></main></body></html>